<?php require_once '../config/auth.php';$page_title='Customers';$base='../';$q=trim($_GET['q']??'');$like="%$q%";$s=$pdo->prepare("SELECT c.*,COUNT(d.id) deals FROM customers c LEFT JOIN deals d ON d.customer_id=c.id WHERE c.name LIKE ? OR c.email LIKE ? OR c.company LIKE ? GROUP BY c.id ORDER BY c.created_at DESC");$s->execute([$like,$like,$like]);$rows=$s->fetchAll();include '../partials/header.php';?><div class="d-flex justify-content-between mb-3"><div><h4>Customers</h4><p class="text-muted">Manage customer relationships.</p></div><a class="btn btn-primary" href="form.php">+ Add customer</a></div><div class="cardx"><form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search name, email or company"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Company</th><th>Phone</th><th>Status</th><th>Deals</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['company'])?></td><td><?=e($r['phone'])?></td><td><span class="status"><?=e(ucfirst($r['status']))?></span></td><td><?=$r['deals']?></td><td><a class="btn btn-sm btn-light" href="form.php?id=<?=$r['id']?>">Edit</a> <a data-confirm="Delete this customer?" class="btn btn-sm btn-outline-danger" href="delete.php?id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div><?php include '../partials/footer.php';?>